import React from "react";
import { motion } from "framer-motion";

const CLIENTS = [
  { name: "Elite Decorators", city: "Delhi" },
  { name: "Royal Events", city: "Mumbai" },
  { name: "Divine Decor", city: "Chandigarh" },
  { name: "Event Palace", city: "Jaipur" },
  { name: "Luxe Events", city: "Lucknow" },
  { name: "Grand Affairs", city: "Bangalore" },
];

const CERTIFICATIONS = [
  { name: "ISO Certified", icon: "🏆" },
  { name: "Premium Quality", icon: "✨" },
  { name: "Pan India Delivery", icon: "🚚" },
  { name: "12+ Years Experience", icon: "⭐" },
];

export default function TrustedBy() {
  return (
    <section className="relative py-16 md:py-24" style={{ background: "linear-gradient(180deg, #fff9ed 0%, #ffffff 100%)" }}>
      <div className="px-6 md:px-12 lg:px-24">

        {/* Certifications */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="flex flex-wrap justify-center gap-6 mb-12"
        >
          {CERTIFICATIONS.map((cert, i) => (
            <div
              key={i}
              className="flex items-center gap-3 px-6 py-3 rounded-full"
              style={{ background: "white", border: "1px solid rgba(212,175,55,0.3)", boxShadow: "0 4px 20px rgba(212,175,55,0.1)" }}
            >
              <span className="text-2xl">{cert.icon}</span>
              <span className="text-sm font-semibold" style={{ color: "#1a080a" }}>{cert.name}</span>
            </div>
          ))}
        </motion.div>

        {/* Trusted By Title */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="text-center mb-10"
        >
          <p className="text-xs tracking-[0.3em] uppercase mb-2" style={{ color: "#d4af37" }}>Trusted By</p>
          <h3 className="serif text-2xl md:text-3xl" style={{ color: "#1a080a" }}>
            India's Top Decorators & Event Planners
          </h3>
        </motion.div>

        {/* Client Logos / Names */}
        <div className="flex flex-wrap justify-center gap-8 md:gap-12">
          {CLIENTS.map((client, i) => (
            <motion.div
              key={i}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: i * 0.1 }}
              className="text-center"
            >
              <div className="px-6 py-4 rounded-lg" style={{ background: "rgba(212,175,55,0.08)", border: "1px solid rgba(212,175,55,0.15)" }}>
                <p className="font-semibold" style={{ color: "#1a080a" }}>{client.name}</p>
                <p className="text-xs mt-1" style={{ color: "rgba(26,8,10,0.5)" }}>{client.city}</p>
              </div>
            </motion.div>
          ))}
        </div>

        {/* Stats Banner */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.8 }}
          className="mt-16 grid grid-cols-2 md:grid-cols-4 gap-4"
        >
          {[
            { num: "5000+", label: "Happy Clients" },
            { num: "98%", label: "Client Satisfaction" },
            { num: "100%", label: "Quality Guaranteed" },
            { num: "24/7", label: "Customer Support" },
          ].map((stat, i) => (
            <div key={i} className="text-center p-6 rounded-xl" style={{ background: "linear-gradient(135deg, #fffdf5, #fff9ed)", border: "1px solid rgba(212,175,55,0.2)" }}>
              <div className="text-3xl md:text-4xl font-bold" style={{ color: "#d4af37" }}>{stat.num}</div>
              <div className="text-xs uppercase tracking-wider mt-2" style={{ color: "rgba(26,8,10,0.5)" }}>{stat.label}</div>
            </div>
          ))}
        </motion.div>
      </div>
    </section>
  );
}
